# -*- coding: utf-8 -*-
"""Run Ragas evaluation against a local, offline document corpus.

This script deliberately bypasses MinerU and Qdrant:

* DOCX files are parsed with python-docx.
* PDF files are parsed with pypdf.
* Retrieved contexts come from a local TF-IDF character n-gram index.
* Answers are generated by the currently configured LLM.
* Ragas consumes question / answer / contexts / ground_truth.
"""
from __future__ import annotations

import argparse
import json
import logging
from pathlib import Path
from typing import Any, Dict, List, Optional

import sys

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from langchain_core.documents import Document
from pypdf import PdfReader
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.metrics.pairwise import cosine_similarity

from src.llms.llm_wrapper import LLMWrapper
from src.parsers.semantic_chunker import SemanticChunker
from src.parsers.smart_parser import ParsedDocument, parse_docx
from src.evaluation.monitor import RagasEvaluator

logger = logging.getLogger(__name__)

DEFAULT_DATA_DIR = (
    r"C:\Users\Administrator\Desktop\工作文件"
)
DEFAULT_DATASET = ROOT / "data" / "eval" / "ragas_test_set.json"


def load_dataset(path: Path) -> Dict[str, Any]:
    with path.open("r", encoding="utf-8") as fh:
        return json.load(fh)


def _load_docx_chunks(file_path: Path) -> List[Document]:
    parsed = parse_docx(str(file_path))
    parsed.extra["file_path"] = str(file_path)
    chunker = SemanticChunker(file_path=str(file_path))
    chunks = chunker.chunk_parsed_doc(parsed)
    for chunk in chunks:
        chunk.metadata["file_path"] = str(file_path)
    return chunks


def _load_pdf_chunks(file_path: Path) -> List[Document]:
    reader = PdfReader(str(file_path))
    chunker = SemanticChunker(file_path=str(file_path))
    chunks: List[Document] = []
    for page_index, page in enumerate(reader.pages, start=1):
        text = page.extract_text() or ""
        if not text.strip():
            continue
        doc = Document(
            page_content=text,
            metadata={
                "source": file_path.name,
                "file_path": str(file_path),
                "page": page_index,
            },
        )
        page_chunks = chunker.chunk_document(doc)
        for chunk in page_chunks:
            chunk.metadata["file_path"] = str(file_path)
        chunks.extend(page_chunks)
    return chunks


def load_local_corpus(
    data_dir: Path,
    selected_files: Optional[List[str]] = None,
) -> List[Document]:
    if not data_dir.exists():
        raise FileNotFoundError(f"数据目录不存在: {data_dir}")

    selected = set(selected_files or [])
    chunks: List[Document] = []
    for path in sorted(data_dir.iterdir()):
        if selected and path.name not in selected:
            continue
        if path.suffix.lower() == ".docx":
            chunks.extend(_load_docx_chunks(path))
        elif path.suffix.lower() == ".pdf":
            chunks.extend(_load_pdf_chunks(path))
    logger.info("本地语料加载完成: %d files -> %d chunks", len(selected), len(chunks))
    return chunks


class OfflineRetriever:
    """Small deterministic lexical retriever for offline testing."""

    def __init__(self, documents: List[Document]) -> None:
        self._documents = documents
        self._vectorizer = TfidfVectorizer(
            analyzer="char_wb",
            ngram_range=(2, 3),
            lowercase=True,
        )
        self._matrix = self._vectorizer.fit_transform(
            [doc.page_content for doc in documents]
        )

    def retrieve(self, query: str, top_k: int = 5) -> List[Dict[str, Any]]:
        query_vec = self._vectorizer.transform([query])
        scores = cosine_similarity(query_vec, self._matrix).ravel()
        order = scores.argsort()[::-1][:top_k]
        results: List[Dict[str, Any]] = []
        for index in order:
            doc = self._documents[index]
            results.append(
                {
                    "text": doc.page_content,
                    "source": doc.metadata.get("source", ""),
                    "file_path": doc.metadata.get("file_path", ""),
                    "page": doc.metadata.get("page", 1),
                    "section_title": doc.metadata.get("section_title", ""),
                    "score": float(scores[index]),
                }
            )
        return results


class QdrantRetriever:
    """Production retrieval path: Qdrant hybrid retrieval + reranker."""

    def retrieve(self, query: str, top_k: int = 5) -> List[Dict[str, Any]]:
        from src.retrievers.pipeline import retrieve as qdrant_retrieve

        docs = qdrant_retrieve(
            query=query,
            top_k=top_k,
            candidate_top_n=max(top_k * 3, 20),
            use_reranker=True,
        )
        results: List[Dict[str, Any]] = []
        for doc in docs:
            score = doc.metadata.get(
                "rerank_score",
                doc.metadata.get("qdrant_score", 0.0),
            )
            results.append(
                {
                    "text": doc.page_content,
                    "source": doc.metadata.get("source", ""),
                    "file_path": doc.metadata.get("file_path", ""),
                    "page": doc.metadata.get("page", 1),
                    "section_title": doc.metadata.get("section_title", ""),
                    "score": float(score),
                }
            )
        return results


def build_retriever(
    mode: str,
    data_dir: Path,
    selected_files: Optional[List[str]],
) -> Any:
    if mode == "local":
        chunks = load_local_corpus(data_dir, selected_files)
        if chunks:
            return OfflineRetriever(chunks)
        raise RuntimeError("本地模式下未加载到任何文档内容")
    return QdrantRetriever()


def retrieve_contexts(
    retriever: Any,
    question: str,
    top_k: int,
) -> List[Dict[str, Any]]:
    try:
        return retriever.retrieve(question, top_k=top_k)
    except Exception as exc:
        logger.warning("检索失败: %s", exc)
        return []


def _build_prompt(contexts: List[str], question: str) -> str:
    context_text = "\n\n".join(
        f"[文档 {i + 1}]\n{text}"
        for i, text in enumerate(contexts)
    )
    return (
        "你是企业知识库问答助手。请严格基于以下资料回答用户问题。"
        "如果资料不足，请明确说明无法回答。\n\n"
        f"--- 资料开始 ---\n{context_text}\n--- 资料结束 ---\n\n"
        f"用户问题：{question}\n"
    )


def generate_answer(
    question: str,
    contexts: List[str],
    use_llm: bool,
) -> str:
    if not use_llm:
        return ""
    try:
        llm = LLMWrapper()
        result = llm.invoke(_build_prompt(contexts, question))
        return result.get("content", "")
    except Exception as exc:
        logger.warning("答案生成失败: %s", exc)
        return f"<generation_error: {exc}>"


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--data-dir", default=DEFAULT_DATA_DIR)
    parser.add_argument("--dataset", default=str(DEFAULT_DATASET))
    parser.add_argument("--top-k", type=int, default=5)
    parser.add_argument("--limit", type=int, default=0)
    parser.add_argument(
        "--retriever",
        choices=("qdrant", "local", "auto"),
        default="qdrant",
    )
    parser.add_argument("--allow-local-fallback", action="store_true")
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--no-llm", action="store_true")
    parser.add_argument("--output", default="")
    args = parser.parse_args()

    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
    )

    dataset = load_dataset(Path(args.dataset))
    items = dataset["items"]
    if args.limit:
        items = items[: args.limit]

    selected_files = dataset.get("meta", {}).get("documents")
    retriever = build_retriever(
        args.retriever,
        Path(args.data_dir),
        selected_files,
    )
    retriever_used = args.retriever
    local_retriever: Optional[OfflineRetriever] = (
        retriever if isinstance(retriever, OfflineRetriever) else None
    )

    if args.retriever == "auto" and local_retriever is None:
        chunks = load_local_corpus(Path(args.data_dir), selected_files)
        local_retriever = OfflineRetriever(chunks) if chunks else None

    questions: List[str] = []
    answers: List[str] = []
    contexts_batch: List[List[str]] = []
    ground_truths: List[str] = []
    item_results: List[Dict[str, Any]] = []

    for item in items:
        question = item["question"]
        retrieved = retrieve_contexts(retriever, question, args.top_k)
        if not retrieved and args.retriever in ("auto", "qdrant"):
            if args.retriever == "auto" or args.allow_local_fallback:
                if local_retriever is not None:
                    retriever = local_retriever
                    retriever_used = "local_fallback"
                    retrieved = retrieve_contexts(
                        retriever,
                        question,
                        args.top_k,
                    )
                elif args.retriever == "qdrant" and args.allow_local_fallback:
                    chunks = load_local_corpus(Path(args.data_dir), selected_files)
                    local_retriever = OfflineRetriever(chunks) if chunks else None
                    if local_retriever is not None:
                        retriever = local_retriever
                        retriever_used = "local_fallback"
                        retrieved = retrieve_contexts(
                            retriever,
                            question,
                            args.top_k,
                        )
        contexts = [r["text"] for r in retrieved]
        answer = generate_answer(
            question,
            contexts,
            use_llm=not args.dry_run and not args.no_llm,
        )

        sources = [r["source"] for r in retrieved]
        source_hit = any(
            expected in sources
            for expected in item.get("expected_sources", [])
        )

        questions.append(question)
        answers.append(answer)
        contexts_batch.append(contexts)
        ground_truths.append(item["ground_truth"])
        item_results.append(
            {
                "id": item["id"],
                "question": question,
                "answer": answer,
                "ground_truth": item["ground_truth"],
                "retrieved_sources": sources,
                "source_hit": source_hit,
                "top_scores": [round(r["score"], 4) for r in retrieved[:3]],
            }
        )

    summary: Dict[str, Any] = {
        "dataset": dataset["meta"]["name"],
        "item_count": len(items),
        "source_hit_count": sum(bool(r["source_hit"]) for r in item_results),
        "source_hit_rate": round(
            sum(bool(r["source_hit"]) for r in item_results) / len(items),
            4,
        ),
        "retriever_used": retriever_used,
    }

    if args.dry_run or args.no_llm:
        summary["ragas_scores"] = {}
        summary["mode"] = "retrieval_only"
    else:
        evaluator = RagasEvaluator()
        ragas_scores = evaluator.evaluate(
            questions=questions,
            answers=answers,
            contexts=contexts_batch,
            ground_truths=ground_truths,
        )
        summary["ragas_scores"] = ragas_scores
        summary["mode"] = "full_ragas"

    output = {
        "summary": summary,
        "items": item_results,
    }
    print(json.dumps(output, ensure_ascii=False, indent=2))

    if args.output:
        output_path = Path(args.output)
        output_path.parent.mkdir(parents=True, exist_ok=True)
        output_path.write_text(
            json.dumps(output, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        logger.info("结果已保存: %s", output_path)


if __name__ == "__main__":
    main()
